def maximum_binary_matrix_score(grid):
 rows,cols=len(grid),len(grid[0]);answer=rows*(1<<(cols-1))
 for c in range(1,cols):
  ones=sum(grid[r][c]==grid[r][0] for r in range(rows));answer+=max(ones,rows-ones)*(1<<(cols-1-c))
 return answer

